-- 013: activities, daily questions, check-in topics, and monthly deep-dive themes.
--
-- DRAFT: requires review before launch. Every row is inserted with review_status = 'draft';
-- mark items 'approved' after review. Pre-launch check:
--   SELECT 'activity', activity_key FROM activities WHERE review_status <> 'approved'
--   UNION ALL SELECT 'question', question FROM daily_questions WHERE active AND review_status <> 'approved'
--   UNION ALL SELECT 'topic', topic_key FROM check_in_topics WHERE review_status <> 'approved'
--   UNION ALL SELECT 'theme', theme_key FROM deep_dive_themes WHERE review_status <> 'approved';
--
-- Generated from authored content (Claude-drafted; each item names its framework).
-- Keeps the sample rows seeded by bond_seed.sql: the four activities and six check-in topics get
-- stable keys (matched by title/name), and the eight daily questions are kept verbatim.
-- Daily questions run in sort_order as a rotation (see the app's daily-question screen);
-- questions no longer in the list are deactivated, not deleted, so past answers keep their question.
--
-- Requires 011_content_architecture.sql. Safe to re-run.

BEGIN;

-- ============ ACTIVITIES (42)
UPDATE activities SET activity_key = 'three-worst-things' WHERE activity_key IS NULL AND title = 'Three Worst Things';
UPDATE activities SET activity_key = 'ideal-day' WHERE activity_key IS NULL AND title = 'Ideal Day';
UPDATE activities SET activity_key = 'memory-lane-walk' WHERE activity_key IS NULL AND title = 'Memory Lane Walk';
UPDATE activities SET activity_key = 'relationship-timeline' WHERE activity_key IS NULL AND title = 'Relationship Timeline';
ON CONFLICT (activity_key) DO UPDATE SET type = EXCLUDED.type, category = EXCLUDED.category, title = EXCLUDED.title, description = EXCLUDED.description, duration = EXCLUDED.duration, difficulty = EXCLUDED.difficulty, framework = EXCLUDED.framework, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;

-- ============ DAILY QUESTIONS (90, in rotation order)
ON CONFLICT (question) DO UPDATE SET category = EXCLUDED.category, depth = EXCLUDED.depth, priority = EXCLUDED.priority, sort_order = EXCLUDED.sort_order, active = TRUE, review_status = EXCLUDED.review_status;
