-- ============ CHECK-IN TOPICS (20)
UPDATE check_in_topics SET topic_key = 'communication' WHERE topic_key IS NULL AND topic_name = 'Communication Check-in';
UPDATE check_in_topics SET topic_key = 'quality-time' WHERE topic_key IS NULL AND topic_name = 'Quality Time';
UPDATE check_in_topics SET topic_key = 'money' WHERE topic_key IS NULL AND topic_name = 'Financial Alignment';
UPDATE check_in_topics SET topic_key = 'intimacy' WHERE topic_key IS NULL AND topic_name = 'Intimacy and Affection';
UPDATE check_in_topics SET topic_key = 'conflict' WHERE topic_key IS NULL AND topic_name = 'Conflict Resolution';
UPDATE check_in_topics SET topic_key = 'future-goals' WHERE topic_key IS NULL AND topic_name = 'Future Goals';
ON CONFLICT (topic_key) DO UPDATE SET topic_name = EXCLUDED.topic_name, description = EXCLUDED.description, category = EXCLUDED.category, depth_level = EXCLUDED.depth_level, framework = EXCLUDED.framework, prompt_questions = EXCLUDED.prompt_questions, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;

-- ============ MONTHLY DEEP-DIVE THEMES (8)
ON CONFLICT (theme_key) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, framework = EXCLUDED.framework, focus_questions = EXCLUDED.focus_questions, weekly_activities = EXCLUDED.weekly_activities, sort_order = EXCLUDED.sort_order, review_status = EXCLUDED.review_status;

COMMIT;
