INSERT INTO activities (activity_key, type, category, title, description, duration, difficulty, framework, content, sort_order, review_status) VALUES
  ('ideal-day', 'conversation_starter', 'connection', 'Ideal Day', 'Share what your ideal day off together would look like.', '15 min', 'easy', 'Gottman Method (love maps)', '{"prompt": "Describe your ideal day off together from morning to night.", "followUp": "What is one thing from each person''s version you could make happen this month?"}'::jsonb, 10, 'draft'),
  ('memory-lane-walk', 'activity', 'connection', 'Memory Lane Walk', 'Take a walk together and share one memory from each year you have been together.', '30 min', 'medium', 'Gottman Method (fondness and admiration)', '{"instructions": ["Find a time to walk together outside.", "Take turns sharing one memory from each year you have been together.", "For each memory, say what it meant to you then and what it means now."], "followUp": "Save one of the memories to Memory Lane."}'::jsonb, 20, 'draft'),
  ('six-second-kiss', 'challenge', 'connection', 'The Six-Second Kiss', 'Swap the quick peck for a kiss long enough to actually feel connected.', '1 week', 'easy', 'Gottman Method (rituals of connection)', '{"instructions": ["For one week, greet and say goodbye to each other with a six-second kiss.", "Notice how it changes the moment of leaving or reuniting."], "followUp": "At the end of the week, talk about whether you want to keep the ritual."}'::jsonb, 30, 'draft'),
  ('stress-reducing-conversation', 'conversation_starter', 'connection', 'Stress-Reducing Conversation', 'A daily check-in about stress outside the relationship, where the listener is fully on the speaker''s side.', '20 min', 'medium', 'Gottman Method', '{"prompt": "What was the most stressful part of your day or week — outside of us?", "instructions": ["Take turns: one person talks for about 10 minutes, then switch.", "The listener shows interest and takes their partner''s side.", "Don''t offer solutions unless asked; understanding comes first."], "rules": "This conversation is only about stress outside the relationship."}'::jsonb, 40, 'draft'),
  ('love-map-questions', 'conversation_starter', 'connection', 'Love Map Update', 'Catch up on each other''s inner world with a few curious questions.', '15 min', 'easy', 'Gottman Method (love maps)', '{"instructions": ["Take turns asking: Who is your closest friend at the moment?", "What is something you''re worried about right now?", "What is something you''re looking forward to?", "What would you do with a completely free day?"], "followUp": "Did any answer surprise you?"}'::jsonb, 50, 'draft'),
  ('reunion-ritual', 'challenge', 'connection', 'Design a Reunion Ritual', 'Create a small, repeatable way to reconnect at the end of each day.', '10 min', 'easy', 'Gottman Method (rituals of connection)', '{"instructions": ["Talk about how your reunions usually go when you get home.", "Design a 5-minute ritual: a hug, a question, a cup of tea together.", "Try it every day for two weeks."], "followUp": "What made the ritual easy or hard to keep?"}'::jsonb, 60, 'draft'),
  ('closeness-questions', 'conversation_starter', 'connection', 'Growing Closer Questions', 'A set of questions that gradually get more personal, designed to build closeness.', '45 min', 'medium', 'Closeness-generating research (Aron et al.)', '{"instructions": ["Take turns answering each question. Go slowly.", "If you could have dinner with anyone, who would it be and why?", "What would a perfect ordinary day look like for you?", "What is something you are deeply grateful for?", "What is a memory you treasure?", "What does friendship mean to you?", "What is something you''ve always wanted to tell me?"], "rules": "Either of you can pass on a question."}'::jsonb, 70, 'draft'),
  ('tech-free-evening', 'challenge', 'connection', 'Tech-Free Evening', 'Spend one evening with phones away and full attention on each other.', '1 evening', 'easy', 'Technoference research', '{"instructions": ["Pick an evening and put both phones in another room.", "Cook, walk, play a game, or just talk.", "Notice what fills the space."], "followUp": "Is there a regular phone-free time you''d like to keep?"}'::jsonb, 80, 'draft'),
  ('three-worst-things', 'conversation_starter', 'communication', 'Three Worst Things', 'Each partner shares three small things that bother them, and the other just listens.', '10 min', 'easy', 'Gottman Method (gentle start-up)', '{"prompt": "What are three small things that bother you in our relationship?", "rules": "No solving during the share — just listening. Then each person picks one to work on."}'::jsonb, 90, 'draft'),
  ('speaker-listener', 'scenario', 'communication', 'Speaker–Listener Practice', 'A structured way to talk about a sensitive topic, one person at a time.', '20 min', 'medium', 'PREP (Speaker–Listener technique)', '{"instructions": ["Choose a small, low-stakes topic.", "The speaker holds an object (the \"floor\") and shares short pieces of their view.", "The listener paraphrases what they heard before responding.", "Switch the floor after a few rounds."], "rules": "The listener doesn''t argue or solve while paraphrasing."}'::jsonb, 100, 'draft'),
  ('soft-startup-rewrite', 'scenario', 'communication', 'Soft Start-Up Rewrite', 'Practice turning a harsh complaint into a gentle request.', '15 min', 'easy', 'Gottman Method (gentle start-up)', '{"prompt": "Rewrite: \"You never help around the house.\"", "instructions": ["Together, rewrite the complaint using \"I feel… about… I need…\".", "Each write one real complaint of your own the same way.", "Read them to each other and notice how they land."]}'::jsonb, 110, 'draft'),
  ('needs-and-requests', 'challenge', 'communication', 'Observation, Feeling, Need, Request', 'Practice making clear requests instead of criticisms.', '15 min', 'easy', 'Nonviolent Communication', '{"instructions": ["Each think of something you''d like to change.", "Write it as: When I see… I feel… because I need… Would you be willing to…?", "Share, and let your partner respond with yes, no, or a counteroffer."]}'::jsonb, 120, 'draft'),
  ('state-of-the-union', 'conversation_starter', 'communication', 'Weekly State of the Union', 'A weekly meeting to appreciate each other and talk through one issue calmly.', '45 min', 'medium', 'Gottman Method', '{"instructions": ["Start with five appreciations each.", "Each share what went well this week.", "Choose one issue; each share your view while the other listens and summarizes.", "End by asking: \"What can I do to make you feel loved this week?\""]}'::jsonb, 130, 'draft'),
  ('validation-practice', 'scenario', 'communication', 'Validation Practice', 'Practice letting your partner know their feelings make sense — even when you see it differently.', '15 min', 'easy', 'Validation (Gottman Method, DBT)', '{"instructions": ["One partner shares a recent frustration (not about the relationship).", "The listener responds with: \"That makes sense because…\"", "Switch roles."], "rules": "Validation isn''t agreement — it''s understanding."}'::jsonb, 140, 'draft'),
  ('repair-phrase-menu', 'challenge', 'conflict', 'Repair Phrase Menu', 'Choose phrases you can use to de-escalate when a conversation heats up.', '10 min', 'easy', 'Gottman Method (repair attempts)', '{"instructions": ["Together, choose phrases you''d welcome in a tense moment, e.g. \"Can we start over?\", \"I''m feeling overwhelmed\", \"I see your point.\"", "Write your favorites down somewhere you''ll both see.", "Agree to accept a repair attempt when it''s offered."]}'::jsonb, 150, 'draft'),
  ('time-out-plan', 'activity', 'conflict', 'Make a Time-Out Plan', 'Agree on how to pause and come back when either of you gets flooded.', '15 min', 'easy', 'Gottman Method (flooding)', '{"instructions": ["Agree on a signal or phrase for \"I need a break.\"", "Agree on how long a break lasts (at least 20 minutes, usually less than 24 hours).", "Decide who will restart the conversation and how.", "During breaks, do something soothing — not rehearsing the argument."]}'::jsonb, 160, 'draft'),
  ('processing-a-past-argument', 'conversation_starter', 'conflict', 'Processing a Past Argument', 'Look back at a past disagreement calmly, to understand each other rather than re-fight it.', '30 min', 'hard', 'Gottman Method (processing a regrettable incident)', '{"instructions": ["Pick an argument that is over and that you both feel calm about now.", "Each share what you felt during it, without debating the facts.", "Each share what you think triggered you — often something older than the argument.", "Each own one part you''d do differently.", "Agree on one thing that would help next time."], "rules": "Stop and take a break if either of you feels flooded. These tools are for couples who feel safe with each other. If you are afraid of your partner, or conflict involves threats, intimidation, or physical harm, relationship exercises are not the right tool. In the US you can reach the National Domestic Violence Hotline at 1-800-799-7233 (or text START to 88788)."}'::jsonb, 170, 'draft'),
  ('dreams-within-conflict', 'conversation_starter', 'conflict', 'Dreams Within Conflict', 'Explore the deeper hopes behind a recurring disagreement.', '30 min', 'hard', 'Gottman Method (gridlock)', '{"prompt": "Choose a recurring disagreement. What deeper hope, value, or story is behind your position?", "instructions": ["One partner speaks about their dream; the other asks curious questions.", "Useful questions: \"What does this mean to you?\", \"Is there a story behind this?\"", "Switch roles, then talk about what you understand now."], "rules": "The goal is understanding, not solving."}'::jsonb, 180, 'draft'),
  ('compromise-circles', 'activity', 'conflict', 'Compromise Circles', 'Find the flexible middle ground in a disagreement.', '20 min', 'medium', 'Gottman Method (accepting influence)', '{"instructions": ["Each draw two circles, one inside the other.", "In the inner circle, write what you can''t give up on this issue.", "In the outer circle, write where you can be flexible.", "Compare and look for a shared plan that respects both inner circles."]}'::jsonb, 190, 'draft'),
  ('yes-and-week', 'challenge', 'conflict', '"Yes, And" Week', 'Practice accepting influence by building on each other''s ideas.', '1 week', 'easy', 'Gottman Method (accepting influence)', '{"instructions": ["For one week, when your partner suggests something, start with \"Yes, and…\" before any \"but\".", "Notice how often you can find something to agree with."], "followUp": "Did it change how decisions felt?"}'::jsonb, 200, 'draft'),
  ('appreciation-jar', 'challenge', 'appreciation', 'Appreciation Jar', 'Collect small notes of appreciation for each other over a week.', '1 week', 'easy', 'Gottman Method (fondness and admiration)', '{"instructions": ["Each day, write one specific thing you appreciated about your partner.", "Put the notes in a jar or shared place.", "At the end of the week, read them together."]}'::jsonb, 210, 'draft'),
  ('gratitude-letter', 'journal', 'appreciation', 'Gratitude Letter', 'Write your partner a letter about a specific way they''ve made your life better.', '30 min', 'medium', 'Positive psychology (gratitude interventions)', '{"instructions": ["Think of a specific time your partner made a difference to you.", "Write about what they did and how it affected you.", "Read it to them, or give it to them to read."]}'::jsonb, 220, 'draft'),
  ('fondness-list', 'journal', 'appreciation', 'Fondness and Admiration List', 'List the qualities you admire in your partner, with examples.', '15 min', 'easy', 'Gottman Method (fondness and admiration)', '{"instructions": ["Each write three qualities you admire in your partner.", "For each one, write a moment when you saw it.", "Share your lists."]}'::jsonb, 230, 'draft'),
  ('three-good-things', 'challenge', 'appreciation', 'Three Good Things, Together', 'End each day by naming three good things — at least one about each other.', '5 min a day', 'easy', 'Positive psychology (three good things)', '{"instructions": ["Each night for a week, each share three good things from the day.", "At least one should be about your partner or your relationship."]}'::jsonb, 240, 'draft'),
  ('celebrate-good-news', 'challenge', 'appreciation', 'Celebrate Good News', 'Practice responding to each other''s good news with real enthusiasm.', '1 week', 'easy', 'Capitalization research (Gable)', '{"instructions": ["For one week, when your partner shares good news, ask two follow-up questions.", "Show genuine enthusiasm and help them savor it."], "followUp": "How did it feel to be celebrated?"}'::jsonb, 250, 'draft'),
  ('shared-values-sort', 'activity', 'values', 'Shared Values Sort', 'Discover which values matter most to each of you, and where they overlap.', '30 min', 'medium', 'Values clarification', '{"instructions": ["Each list your top ten values (e.g. family, adventure, security, faith, creativity).", "Narrow to your top five.", "Compare lists: which values overlap and which differ?", "Talk about how your shared values show up in daily life."]}'::jsonb, 260, 'draft'),
  ('rituals-of-connection', 'conversation_starter', 'values', 'Our Rituals', 'Talk about the rituals that make your relationship feel like yours.', '20 min', 'medium', 'Gottman Method (shared meaning)', '{"prompt": "How do we want to mark mornings, weekends, holidays, birthdays, and hard days?", "followUp": "Choose one ritual to start or strengthen."}'::jsonb, 270, 'draft'),
  ('money-stories', 'conversation_starter', 'values', 'Money Stories', 'Share what money meant in each of your families growing up.', '25 min', 'medium', 'Financial relationship research', '{"instructions": ["What was money like in your family growing up?", "What does money mean to you now: security, freedom, generosity, or something else?", "Where do your money values overlap?"]}'::jsonb, 280, 'draft'),
  ('five-year-vision', 'journal', 'values', 'Five-Year Vision', 'Imagine your life together five years from now, then compare notes.', '30 min', 'medium', 'Gottman Method (shared meaning)', '{"instructions": ["Each write a short description of an ordinary day five years from now.", "Include home, work, relationships, and how you spend time together.", "Share and look for common threads."]}'::jsonb, 290, 'draft'),
  ('load-audit', 'activity', 'values', 'Household Load Audit', 'Make the invisible work of running your life visible, and share it fairly.', '30 min', 'medium', 'Household labor research', '{"instructions": ["List every recurring task, including planning and remembering tasks.", "Mark who currently notices, plans, and does each one.", "Choose one area to hand over fully, from noticing to finishing."]}'::jsonb, 300, 'draft'),
  ('closeness-ranking', 'conversation_starter', 'intimacy', 'Kinds of Closeness', 'Compare how much each of you values emotional, physical, intellectual, and shared-time closeness.', '15 min', 'easy', 'Intimacy process research', '{"instructions": ["Each rank emotional, physical, intellectual, and shared-experience closeness.", "Share your rankings and an example of each.", "Plan one moment this week for each partner''s top kind."]}'::jsonb, 310, 'draft'),
  ('affection-menu', 'activity', 'intimacy', 'Affection Menu', 'Create a menu of everyday, non-sexual affection you each enjoy.', '15 min', 'easy', 'Couple intimacy practice', '{"instructions": ["Each list small kinds of affection you enjoy (holding hands, a back rub, a hug from behind).", "Mark your favorites.", "Try one item from your partner''s menu every day this week."]}'::jsonb, 320, 'draft'),
  ('novelty-date', 'challenge', 'fun', 'Something New Date', 'Plan a date doing something neither of you has done before.', '1–3 hours', 'easy', 'Self-expansion research', '{"instructions": ["Brainstorm activities neither of you has tried.", "Pick one and put it on the calendar.", "Afterwards, share what surprised you."]}'::jsonb, 330, 'draft'),
  ('playlist-of-us', 'activity', 'fun', 'Playlist of Us', 'Build a playlist of songs tied to your relationship.', '20 min', 'easy', 'Shared memory and play', '{"instructions": ["Each add five songs that remind you of moments together.", "Listen together and share the story behind each."]}'::jsonb, 340, 'draft'),
  ('would-you-rather', 'conversation_starter', 'fun', 'Would You Rather', 'Playful questions to laugh and learn about each other.', '10 min', 'easy', 'Play and positive affect', '{"instructions": ["Would you rather travel to the past or the future?", "Would you rather live by the beach or in the mountains?", "Would you rather have a quiet night in or a spontaneous adventure?", "Take turns inventing your own."]}'::jsonb, 350, 'draft'),
  ('cook-together', 'challenge', 'fun', 'Cook Something New', 'Cook a recipe neither of you has made before.', '1 hour', 'easy', 'Self-expansion research', '{"instructions": ["Choose a new recipe together.", "Split the tasks and cook side by side.", "Rate the result together — honestly and kindly."]}'::jsonb, 360, 'draft'),
  ('play-date', 'challenge', 'fun', 'Childhood Play Date', 'Play a game you each loved as a kid.', '30 min', 'easy', 'Play and positive affect', '{"instructions": ["Each share a favorite childhood game.", "Play both games together.", "Share one memory the games brought back."]}'::jsonb, 370, 'draft'),
  ('relationship-timeline', 'journal', 'milestones', 'Relationship Timeline', 'Create a timeline of your relationship milestones together.', '20 min', 'easy', 'Gottman Method (oral history)', '{"instructions": ["Mark when you met, your first date, and your first trip.", "Add challenges you overcame together.", "Include moments of joy and growth."]}'::jsonb, 380, 'draft'),
  ('how-we-met', 'conversation_starter', 'milestones', 'Retell How We Met', 'Tell the story of how you met and fell for each other — together.', '20 min', 'easy', 'Gottman Method (oral history)', '{"instructions": ["Take turns telling the story of how you met.", "What did you first notice about each other?", "When did you know this was something special?"]}'::jsonb, 390, 'draft'),
  ('hard-times-we-survived', 'conversation_starter', 'milestones', 'Hard Times We Got Through', 'Remember challenges you faced together and what helped.', '20 min', 'medium', 'We-ness research', '{"instructions": ["Each name a hard time you went through together.", "Talk about what helped you get through it.", "Name one strength as a couple it revealed."]}'::jsonb, 400, 'draft'),
  ('anniversary-letter', 'journal', 'milestones', 'Anniversary Letter', 'Write a letter looking back on the past year together and ahead to the next.', '30 min', 'medium', 'Gottman Method (shared meaning)', '{"instructions": ["Write about three moments from the past year you''re grateful for.", "Write one thing you learned about your partner.", "Write one hope for the coming year.", "Exchange and read the letters."]}'::jsonb, 410, 'draft'),
  ('year-ahead', 'activity', 'milestones', 'Plan the Year Ahead', 'Set a few shared intentions for the coming year.', '45 min', 'medium', 'Goal-setting practice', '{"instructions": ["Each share one hope for yourself and one for your relationship.", "Choose two or three shared intentions.", "Put a check-in on the calendar in three months."]}'::jsonb, 420, 'draft')
INSERT INTO daily_questions (question, category, depth, priority, sort_order, active, review_status) VALUES
