  ('What''s one thing that made today harder than you expected?', 'communication', 'light', 1, 29, TRUE, 'draft'),
  ('What''s something small you''d love for us to do together this week?', 'connection', 'light', 1, 30, TRUE, 'draft'),
  ('When do you feel most connected to me?', 'connection', 'medium', 2, 31, TRUE, 'draft'),
  ('What''s something hard you went through that shaped who you are?', 'memories', 'deep', 3, 32, TRUE, 'draft'),
  ('If we had a free Saturday with no plans, how would you want to spend it?', 'fun', 'light', 1, 33, TRUE, 'draft'),
  ('What''s a small promise I kept that meant a lot to you?', 'gratitude', 'medium', 2, 34, TRUE, 'draft'),
