  ('What''s one thing you''d like us to learn together?', 'goals', 'medium', 2, 46, TRUE, 'draft'),
  ('What''s something you''re still learning to accept about yourself?', 'growth', 'deep', 3, 47, TRUE, 'draft'),
  ('What''s something you appreciated about me this week?', 'gratitude', 'light', 1, 48, TRUE, 'draft'),
  ('What''s something I do that helps you feel calm when you''re stressed?', 'connection', 'medium', 2, 49, TRUE, 'draft'),
  ('What''s something you''ve learned recently that surprised you?', 'growth', 'light', 1, 50, TRUE, 'draft'),
  ('What''s something you admire about how I handle hard things?', 'gratitude', 'medium', 2, 51, TRUE, 'draft'),
  ('What''s a moment in our relationship you''d like to revisit or talk through?', 'communication', 'deep', 3, 52, TRUE, 'draft'),
  ('What''s a smell, sound, or taste that reminds you of us?', 'memories', 'light', 1, 53, TRUE, 'draft'),
  ('What part of our home feels most like "us"?', 'values', 'medium', 2, 54, TRUE, 'draft'),
