  ('What''s a question you wish I asked you more often?', 'communication', 'medium', 2, 60, TRUE, 'draft'),
  ('What''s a kind thing you noticed me do recently?', 'gratitude', 'light', 1, 61, TRUE, 'draft'),
  ('What''s your favorite photo of us, and why?', 'memories', 'light', 1, 62, TRUE, 'draft'),
  ('How would you like us to spend our next anniversary?', 'goals', 'medium', 2, 63, TRUE, 'draft'),
  ('What''s a hope you have for us that you haven''t said out loud?', 'goals', 'deep', 3, 64, TRUE, 'draft'),
  ('What moment today would you want to replay?', 'connection', 'light', 1, 65, TRUE, 'draft'),
  ('How do you most like to be comforted when you''re sad?', 'connection', 'medium', 2, 66, TRUE, 'draft'),
  ('What''s a movie or show you''d happily rewatch with me?', 'fun', 'light', 1, 67, TRUE, 'draft'),
  ('How would you like us to support each other''s individual growth?', 'growth', 'deep', 3, 68, TRUE, 'draft'),
  ('What''s something you''re proud of us for?', 'gratitude', 'medium', 2, 69, TRUE, 'draft'),
  ('What''s your favorite way for me to greet you when we see each other?', 'connection', 'light', 1, 70, TRUE, 'draft'),
  ('What''s something from your family you''d like us to do differently?', 'values', 'medium', 2, 71, TRUE, 'draft'),
  ('Is there a conversation we keep avoiding that you''d like to have gently?', 'communication', 'deep', 3, 72, TRUE, 'draft'),
  ('If you could have any skill instantly, what would it be?', 'fun', 'light', 1, 73, TRUE, 'draft'),
  ('What''s one boundary that helps you feel respected?', 'communication', 'medium', 2, 74, TRUE, 'draft'),
  ('What''s a way I could make tomorrow morning easier for you?', 'connection', 'light', 1, 75, TRUE, 'draft'),
  ('What do you need from me when you''re overwhelmed?', 'connection', 'deep', 3, 76, TRUE, 'draft'),
  ('What would your perfect breakfast together look like?', 'fun', 'light', 1, 77, TRUE, 'draft'),
