  ('What makes you feel most respected by me?', 'values', 'deep', 3, 80, TRUE, 'draft'),
  ('What does a really good week look like for you?', 'connection', 'medium', 2, 81, TRUE, 'draft'),
  ('What small luxury makes your day better?', 'fun', 'light', 1, 82, TRUE, 'draft'),
