  ('What''s a way I show love that you''d like to see more often?', 'connection', 'medium', 2, 86, TRUE, 'draft'),
  ('What''s a new thing you''d like to try this month?', 'fun', 'light', 1, 87, TRUE, 'draft'),
  ('When do you feel most alone in our relationship, and what would help?', 'connection', 'deep', 3, 88, TRUE, 'draft'),
  ('What''s a moment you felt really understood by me?', 'connection', 'medium', 2, 89, TRUE, 'draft'),
  ('If our relationship had a theme song, what would it be?', 'fun', 'light', 1, 90, TRUE, 'draft')
INSERT INTO check_in_topics (topic_key, topic_name, description, category, depth_level, framework, prompt_questions, sort_order, review_status) VALUES
  ('communication', 'Communication Check-in', 'How well are you and your partner communicating lately?', 'communication', 1, 'Gottman Method', ARRAY['How has our communication been this week?', 'Is there anything unsaid that you would like to share?', 'What could we do to feel more heard by each other?']::text[], 10, 'draft'),
  ('quality-time', 'Quality Time', 'Are you spending enough meaningful time together?', 'fun', 1, 'Rituals of connection', ARRAY['How much quality time have we spent together recently?', 'What activities bring us the most joy?', 'Do we need to schedule more time together?']::text[], 20, 'draft'),
  ('money', 'Financial Alignment', 'Are you and your partner on the same page about money?', 'finances', 2, 'Financial relationship research', ARRAY['Do we have any financial stresses to talk about?', 'Are we aligned on our spending priorities?', 'What financial goal would we like to work toward together?']::text[], 30, 'draft'),
  ('intimacy', 'Intimacy and Affection', 'How is your physical and emotional closeness?', 'intimacy', 2, 'Intimacy process research', ARRAY['How connected have you felt to me lately?', 'Is there anything you''d like more or less of?', 'What''s one way we could nurture our closeness this week?']::text[], 40, 'draft'),
  ('conflict', 'Conflict Resolution', 'How are disagreements being handled in your relationship?', 'conflict', 2, 'Gottman Method', ARRAY['Have we had any disagreements that still feel unresolved?', 'How have we handled disagreements recently?', 'What would help us argue more kindly?']::text[], 50, 'draft'),
  ('future-goals', 'Future Goals', 'Are you both working toward common goals?', 'goals', 2, 'Gottman Method (shared meaning)', ARRAY['What goals are we working toward together?', 'Are our individual goals supporting each other?', 'What support do you need from me?']::text[], 60, 'draft'),
  ('stress-support', 'Stress and Support', 'How is stress from outside the relationship affecting you both?', 'wellbeing', 1, 'Dyadic coping research', ARRAY['What''s been the biggest source of stress for you lately?', 'What kind of support helps you most right now: listening, practical help, or space?', 'Is there anything I could take off your plate this week?']::text[], 70, 'draft'),
  ('appreciation', 'Appreciation', 'Are you noticing and naming what you value in each other?', 'appreciation', 1, 'Gottman Method (fondness and admiration)', ARRAY['What''s something I did recently that you appreciated?', 'Do you feel noticed for the things you do?', 'How could we make appreciation part of our routine?']::text[], 80, 'draft'),
  ('household-load', 'Household Load', 'Does the work of running your life feel fairly shared?', 'home', 2, 'Household labor research', ARRAY['Which tasks feel heaviest for you right now?', 'Is there any invisible work — planning, remembering — you''d like me to notice?', 'What''s one area we could rebalance?']::text[], 90, 'draft'),
  ('family', 'Family and In-Laws', 'How are you handling relationships with extended family?', 'family', 2, 'Family systems practice', ARRAY['Are there any family situations coming up that we should plan for?', 'Do you feel supported by me around my family, and I by you around yours?', 'Is there a boundary we''d like to set together?']::text[], 100, 'draft'),
  ('trust', 'Trust and Reliability', 'Do you feel you can count on each other?', 'trust', 2, 'Gottman Method (trust)', ARRAY['Is there a promise, big or small, that''s been slipping?', 'When have you felt most able to rely on me recently?', 'What would help you feel more secure in us?']::text[], 110, 'draft'),
  ('emotional-safety', 'Emotional Safety', 'Does it feel safe to share softer feelings with each other?', 'connection', 3, 'Emotionally Focused Therapy', ARRAY['Is there a feeling you''ve been holding back from sharing?', 'How do you know when I''m really listening?', 'What helps you feel safe to be vulnerable with me?']::text[], 120, 'draft'),
  ('fun', 'Fun and Play', 'Is there enough lightness and laughter in your relationship?', 'fun', 1, 'Self-expansion research', ARRAY['When did we last really laugh together?', 'Is there something new you''d like us to try?', 'What could we do just for fun this month?']::text[], 130, 'draft'),
  ('health', 'Health and Energy', 'How are your energy, sleep, and well-being affecting the relationship?', 'wellbeing', 1, 'Health and relationships research', ARRAY['How has your energy and sleep been lately?', 'Is there a health goal you''d like support with?', 'How can we look after each other''s well-being this week?']::text[], 140, 'draft'),
  ('parenting', 'Parenting Teamwork', 'If you''re parents, are you working together as a team?', 'family', 2, 'Gottman Method (Bringing Baby Home)', ARRAY['Where do we work well together as parents?', 'Is there a parenting decision we need to align on?', 'How can we protect time for just the two of us?']::text[], 150, 'draft'),
  ('screens', 'Screens and Attention', 'Are phones and screens getting in the way of connection?', 'connection', 1, 'Technoference research', ARRAY['Are there times you wish I were less on my phone?', 'Are there times I''d like the same from you?', 'Is there a screen-free time we''d like to protect?']::text[], 160, 'draft'),
  ('personal-growth', 'Personal Growth', 'Are you supporting each other''s individual goals?', 'growth', 2, 'Self-expansion research', ARRAY['What''s something you''re working on for yourself?', 'How can I support it?', 'Is there anything that makes it hard to grow right now?']::text[], 170, 'draft'),
  ('rituals', 'Rituals and Traditions', 'Are your rituals and traditions still meaningful?', 'values', 1, 'Gottman Method (shared meaning)', ARRAY['Which of our rituals do you love most?', 'Is there a ritual that''s slipped away that you miss?', 'Is there a new tradition you''d like to start?']::text[], 180, 'draft'),
  ('repair', 'Repair Check', 'Have recent hurts or disagreements been repaired?', 'conflict', 3, 'Gottman Method (repair)', ARRAY['Is there a recent moment that still stings?', 'Is there something you''d like to apologize for, or hear an apology for?', 'What would help us feel fully back on track?']::text[], 190, 'draft'),
  ('needs', 'Needs and Requests', 'Are you each able to ask for what you need?', 'communication', 2, 'Nonviolent Communication', ARRAY['Is there a need of yours that isn''t being met right now?', 'How could you phrase it as a request?', 'Is there anything that makes asking hard?']::text[], 200, 'draft')
INSERT INTO deep_dive_themes (theme_key, title, summary, framework, focus_questions, weekly_activities, sort_order, review_status) VALUES
  ('communication', 'Communication', 'A month of listening better and speaking more gently.', 'Gottman Method; Nonviolent Communication', '["When do you feel most heard by me?", "What topics feel hardest for us to talk about?", "How do you like to be approached with a concern?", "What''s one communication habit we''d like to build?"]'::jsonb, '[{"week": 1, "title": "Notice your patterns", "description": "Each week, notice one moment of great communication and one moment that went sideways."}, {"week": 2, "title": "Gentle start-ups", "description": "Practice raising one small concern with \"I feel… about… I need…\"."}, {"week": 3, "title": "Listening deeply", "description": "Try the Speaker–Listener practice on a low-stakes topic."}, {"week": 4, "title": "State of the union", "description": "Hold a weekly meeting: appreciations, what went well, and one issue."}]'::jsonb, 10, 'draft'),
  ('appreciation', 'Appreciation and Fondness', 'A month of noticing and naming what you value in each other.', 'Gottman Method (fondness and admiration)', '["What first drew you to me?", "What quality of mine do you admire most?", "When do you feel most appreciated?", "How can we make appreciation a daily habit?"]'::jsonb, '[{"week": 1, "title": "Fondness list", "description": "Each write three qualities you admire in the other, with examples."}, {"week": 2, "title": "Appreciation jar", "description": "Add a note of appreciation every day."}, {"week": 3, "title": "Gratitude letter", "description": "Write and share a letter about a time your partner made a difference."}, {"week": 4, "title": "Celebrate each other", "description": "Plan a small celebration of something your partner did this month."}]'::jsonb, 20, 'draft'),
  ('conflict-repair', 'Conflict and Repair', 'A month of handling disagreements with more calm and quicker repair.', 'Gottman Method', '["How do you usually feel during our disagreements?", "What helps you calm down when you''re upset?", "What''s a recurring topic we could understand better?", "How do you like to repair after an argument?"]'::jsonb, '[{"week": 1, "title": "Time-out plan", "description": "Agree on a signal and plan for taking breaks when flooded."}, {"week": 2, "title": "Repair phrase menu", "description": "Choose phrases you''d welcome in tense moments."}, {"week": 3, "title": "Dreams within conflict", "description": "Explore the deeper hopes behind one recurring disagreement."}, {"week": 4, "title": "Process a past argument", "description": "Look back calmly at a past disagreement to understand each other."}]'::jsonb, 30, 'draft'),
  ('intimacy', 'Intimacy and Closeness', 'A month of building emotional and physical closeness.', 'Intimacy process research', '["What makes you feel closest to me?", "Which kind of closeness do you feel is missing?", "What helps you feel relaxed and open with me?", "How can we protect time for intimacy?"]'::jsonb, '[{"week": 1, "title": "Kinds of closeness", "description": "Rank emotional, physical, intellectual, and shared-experience closeness."}, {"week": 2, "title": "Affection menu", "description": "Share everyday affection you each enjoy, and use it."}, {"week": 3, "title": "An appreciative conversation", "description": "Share what you appreciate about your physical connection."}, {"week": 4, "title": "Protected evening", "description": "Plan an evening with no screens and no chores."}]'::jsonb, 40, 'draft'),
  ('trust', 'Trust and Reliability', 'A month of strengthening the everyday trust between you.', 'Gottman Method (trust); attachment research', '["When have you felt you could really count on me?", "Which areas of trust feel strongest?", "Is there a small promise that''s been slipping?", "What helps you feel secure in us?"]'::jsonb, '[{"week": 1, "title": "Trust inventory", "description": "Rate how solid different areas of trust feel, and talk about it."}, {"week": 2, "title": "Promise check", "description": "Review the small promises you''ve made and keep them."}, {"week": 3, "title": "Turning toward", "description": "Notice and respond to each other''s bids for attention."}, {"week": 4, "title": "A softer feeling", "description": "Share a feeling that sits beneath a recent frustration."}]'::jsonb, 50, 'draft'),
  ('shared-dreams', 'Shared Dreams and Meaning', 'A month of exploring what you''re building together.', 'Gottman Method (shared meaning)', '["What are your biggest dreams for our life together?", "What values do we want our relationship to reflect?", "Which rituals make us feel like \"us\"?", "What would you like our life to look like in five years?"]'::jsonb, '[{"week": 1, "title": "Values sort", "description": "Each choose your top five values and compare them."}, {"week": 2, "title": "Our rituals", "description": "Talk about how you want to mark mornings, weekends, and holidays."}, {"week": 3, "title": "Five-year vision", "description": "Each describe an ordinary day five years from now."}, {"week": 4, "title": "Plan the year", "description": "Choose two or three shared intentions for the year ahead."}]'::jsonb, 60, 'draft'),
  ('money', 'Money and Values', 'A month of understanding each other''s money story and working as a team.', 'Financial relationship research', '["What did money mean in your family growing up?", "What does financial security look like to you?", "Where do our spending priorities differ?", "What''s a financial goal we share?"]'::jsonb, '[{"week": 1, "title": "Money stories", "description": "Share what money was like in each of your families."}, {"week": 2, "title": "Spending priorities", "description": "Each list your top three spending priorities and compare."}, {"week": 3, "title": "Money date", "description": "Hold a calm monthly review of spending and goals."}, {"week": 4, "title": "A shared goal", "description": "Choose one financial goal and a first step."}]'::jsonb, 70, 'draft'),
  ('stress-support', 'Stress and Support', 'A month of facing outside stress as a team.', 'Dyadic coping research', '["What''s the biggest stress in your life right now?", "How does stress show up in how we treat each other?", "What kind of support helps you most?", "How can we protect our relationship during busy seasons?"]'::jsonb, '[{"week": 1, "title": "Stress map", "description": "Each name your current stresses and how they affect you."}, {"week": 2, "title": "Stress-reducing conversations", "description": "Hold short daily check-ins about stress outside the relationship."}, {"week": 3, "title": "Support menu", "description": "Each list the kinds of support you find most helpful."}, {"week": 4, "title": "Recharge together", "description": "Plan one restful activity together."}]'::jsonb, 80, 'draft')
